mapper.select:
SELECT

FROM order_master om
WHERE om.sys_id = #{consumerSessionId}
  AND om.link_sys_id = #{tableSysId}
  AND om.sys_plant_cd = #{sysPlantCd}
  AND om.insert_user_id = 'CONSUMER'

SELECT sys_id
FROM order_master
WHERE sys_id = #{consumerSessionId}
  AND link_sys_id = #{tableSysId}
  AND sys_plant_cd = #{sysPlantCd}
  AND insert_user_id = 'CONSUMER'
FOR UPDATE

mapper.delete:
DELETE FROM order_master om
WHERE om.sys_id = #{consumerSessionId}
  AND om.link_sys_id = #{tableSysId}
  AND om.sys_plant_cd = #{sysPlantCd}
  AND om.insert_user_id = 'CONSUMER'
  AND om.order_status = '01'
  AND COALESCE(om.modify_datetime, om.insert_datetime) < NOW() - INTERVAL '5 minutes'
  AND NOT EXISTS (
      SELECT 1
      FROM order_group og
      WHERE og.link_sys_id = om.sys_id
  )

mapper.update:
UPDATE order_master
SET modify_datetime = NOW()
WHERE sys_id = #{consumerSessionId}
  AND link_sys_id = #{tableSysId}
  AND sys_plant_cd = #{sysPlantCd}
  AND insert_user_id = 'CONSUMER'
  AND order_status = '01'
